#!/usr/bin/env bash
# Question 13: Canary by request header. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl get ingressclass traefik >/dev/null 2>&1 && kubectl get gatewayclass traefik >/dev/null 2>&1 || {
  echo "this cluster image has no Traefik or Gateway API: rebuild images with ./cka images build --force" >&2
  exit 1
}
mkdir -p /opt/course
mkdir -p /root/.cka-tls-${Q13_NS}-app
openssl req -x509 -newkey rsa:2048 -nodes -days 30 -subj "/CN=app.${Q13_NS}.lab" -addext "subjectAltName=DNS:app.${Q13_NS}.lab" -keyout /root/.cka-tls-${Q13_NS}-app/tls.key -out /root/.cka-tls-${Q13_NS}-app/tls.crt 2>/dev/null
chown -R ubuntu:ubuntu /opt/course
kubectl create namespace "${Q13_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q13_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q13_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl -n "${Q13_NS}" create deployment web --image=nginx:1.27-alpine --port=80 --dry-run=client -o yaml | kubectl apply -f - >/dev/null
kubectl -n "${Q13_NS}" expose deployment web --port=80 --dry-run=client -o yaml | kubectl apply -f - >/dev/null
kubectl apply -f - <<EOF >/dev/null
apiVersion: apps/v1
kind: Deployment
metadata:
  name: web-canary
  namespace: ${Q13_NS}
spec:
  replicas: 1
  selector:
    matchLabels: { app: web-canary }
  template:
    metadata:
      labels: { app: web-canary }
    spec:
      containers:
        - name: web
          image: busybox:1.36
          command: ["sh", "-c", "mkdir -p /www && echo canary ${Q13_NS} > /www/index.html && httpd -f -p 80 -h /www"]
---
apiVersion: v1
kind: Service
metadata:
  name: web-canary
  namespace: ${Q13_NS}
spec:
  selector: { app: web-canary }
  ports: [{ port: 80 }]
EOF
kubectl -n "${Q13_NS}" create secret tls app-tls --cert=/root/.cka-tls-${Q13_NS}-app/tls.crt --key=/root/.cka-tls-${Q13_NS}-app/tls.key --dry-run=client -o yaml | kubectl apply -f - >/dev/null
kubectl -n "${Q13_NS}" delete httproute web --ignore-not-found >/dev/null
kubectl apply -f - <<EOF >/dev/null
apiVersion: gateway.networking.k8s.io/v1
kind: Gateway
metadata:
  name: app-gw
  namespace: ${Q13_NS}
spec:
  gatewayClassName: traefik
  listeners:
    - name: https
      protocol: HTTPS
      port: 8443
      hostname: app.${Q13_NS}.lab
      tls:
        mode: Terminate
        certificateRefs: [{ kind: Secret, name: app-tls }]
---
apiVersion: gateway.networking.k8s.io/v1
kind: HTTPRoute
metadata:
  name: web
  namespace: ${Q13_NS}
spec:
  parentRefs: [{ name: app-gw, sectionName: https }]
  hostnames: [app.${Q13_NS}.lab]
  rules:
    - backendRefs: [{ name: web, port: 80 }]
EOF
kubectl -n "${Q13_NS}" rollout status deployment/web --timeout=180s >/dev/null
kubectl -n "${Q13_NS}" rollout status deployment/web-canary --timeout=180s >/dev/null
for _ in $(seq 1 30); do
  curl -sk -m 5 --resolve app.${Q13_NS}.lab:30443:$(getent hosts controlplane | awk '{print $1}') https://app.${Q13_NS}.lab:30443/ | grep -q 'Welcome to nginx' && break
  sleep 2
done
: "${Q13_NS}"
